def simplify(apps, schema_editor):
    """Albums now take at most 30 days after approval, and production has four steps."""
    apps.get_model("photopholio", "AlbumStyle").objects.update(delivery_days_min=30, delivery_days_max=30)
    Order = apps.get_model("photopholio", "AlbumOrder")
    Order.objects.update(delivery_days_min=30, delivery_days_max=30)
    Order.objects.filter(production_status__in=["ordered", "printed", "packed"]).update(production_status="printing")
    # the design fee is now released when the customer approves the design
    Order.objects.filter(status="paid", design_status="approved", payout_status="held").update(payout_status="ready")


